DROP TABLE IF EXISTS `screenings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `screenings` (
  `ScreeningID` int NOT NULL AUTO_INCREMENT,
  `MovieID` int NOT NULL,
  `RoomID` int NOT NULL,
  `ScreeningDate` date NOT NULL,
  `ScreeningTime` time NOT NULL,
  `BasePrice` decimal(10,2) NOT NULL DEFAULT '60000.00',
  PRIMARY KEY (`ScreeningID`),
  KEY `MovieID` (`MovieID`),
  KEY `RoomID` (`RoomID`),
  CONSTRAINT `screenings_ibfk_1` FOREIGN KEY (`MovieID`) REFERENCES `movies` (`MovieID`) ON DELETE CASCADE,
  CONSTRAINT `screenings_ibfk_2` FOREIGN KEY (`RoomID`) REFERENCES `cinemarooms` (`RoomID`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=511 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

